// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        // Only the deployer (this test contract, c's owner) may invoke the function;
        // other callers legitimately revert, so restrict to the owner.
        vm.deal(address(c), amount);
        uint256 before = address(this).balance;
        vm.prank(address(this));
        c.sudicideAnyone();
        assertTrue(address(this).balance == before + amount && address(c).balance == 0);
    }
}
